const tabId = 480038377;
const allCards = await browserjs(tabId, () => {
  return Array.from(document.querySelectorAll(".simo_card")).map((c, idx) => {
    const text = c.innerText;
    // Extract provider from "Get deal via [Provider]"
    const providerMatch = text.match(/Get deal via ([^\n\*]+)/i);
    // Extract data
    const dataMatch = text.match(/5G data\s*([\d\.]+\s*(?:GB|MB|unlimited))/i) || text.match(/([\d\.]+\s*(?:GB|MB))/i);
    // Contract
    const contractMatch = text.match(/Contract\s*([^\n]+)/i);
    // Mins/texts
    const minsMatch = text.match(/Mins\/texts\s*([^\n]+)/i);
    // Equivalent cost
    const equivMatch = text.match(/Equivalent cost[^:]*:\s*([^\n]+)/i);
    // Standard / monthly pricing lines
    const monthPrices = Array.from(text.matchAll(/Months? [^\n]+\n(£[^\n\/]+\/mth)/gi)).map(m => m[0]);
    const thereafterMatch = text.match(/Thereafter\s*\n(£[^\n\/]+\/mth)/i);

    return {
      index: idx + 1,
      id: c.id,
      provider: providerMatch ? providerMatch[1].trim() : "Unknown",
      data: dataMatch ? dataMatch[1].trim() : "Unknown",
      contract: contractMatch ? contractMatch[1].trim() : "Unknown",
      minsTexts: minsMatch ? minsMatch[1].trim() : "Unknown",
      equivPrice: equivMatch ? equivMatch[1].trim() : "Unknown",
      monthPrices,
      thereafter: thereafterMatch ? thereafterMatch[1].trim() : null,
      fullTextSnippet: text.slice(0, 400).replace(/\n+/g, " | ")
    };
  });
});

