const tabId = 480038377;
const selectParents = await browserjs(tabId, () => {
  const dataSelect = document.getElementById("data");
  if (!dataSelect) return "data select not found";
  let parent = dataSelect.parentElement;
  let ancestors = [];
  while (parent && ancestors.length < 5) {
    ancestors.push({
      tag: parent.tagName,
      id: parent.id,
      className: parent.className
    });
    parent = parent.parentElement;
  }
  return {
    ancestors,
    form: dataSelect.closest("form") ? {
      id: dataSelect.closest("form").id,
      className: dataSelect.closest("form").className,
      action: dataSelect.closest("form").action
    } : null
  };
});
