const resultsHtml = await browserjs(tabId, () => {
  // Find where results are rendered
  const resultsContainer = document.querySelector("#results") || document.querySelector(".results") || document.querySelector("#deal-results") || document.querySelector("#deals");
  if (resultsContainer) {
    return { found: "container", html: resultsContainer.innerHTML.slice(0, 1000) };
  }
  // Let's search for elements containing £
  const pounds = Array.from(document.querySelectorAll("*")).filter(el => {
    return el.children.length === 0 && el.textContent.includes("£") && /\d/.test(el.textContent);
  }).map(el => ({
    tag: el.tagName,
    text: el.textContent.trim(),
    parentClass: el.parentElement ? el.parentElement.className : ""
  }));
  return { found: "pounds", count: pounds.length, sample: pounds.slice(0, 10) };
});

console.log(JSON.stringify(resultsHtml, null, 2));

