const tabId = 480038377;
const deals = await browserjs(tabId, () => {
  // Let's find each deal row or card
  // Look for elements with class containing 'deal' or 'simo'
  const rows = Array.from(document.querySelectorAll("[class*='deal'], [class*='simo_deal']"));

  // Or let's inspect elements that contain simo_pricing
  const priceElements = Array.from(document.querySelectorAll(".simo_pricing_equiv, .simo_pricing_cost, .simo_pricing"));

  // Let's find parent containers
  const dealContainers = new Set();
  priceElements.forEach(el => {
    let curr = el;
    while (curr && curr !== document.body) {
      if (curr.classList.contains("deal") || curr.classList.contains("simo_deal") || curr.id.includes("deal") || curr.getAttribute("data-deal-id")) {
        dealContainers.add(curr);
        break;
      }
      curr = curr.parentElement;
    }
  });

  return {
    rowsFound: rows.length,
    dealContainersFound: dealContainers.size,
    containers: Array.from(dealContainers).map(c => ({
      id: c.id,
      className: c.className,
      text: c.innerText.replace(/\n+/g, " | ").slice(0, 300)
    }))
  };
});

console.log(JSON.stringify(deals, null, 2));

