  const equiv = document.querySelector(".simo_pricing_equiv");
  if (!equiv) return "No .simo_pricing_equiv found";
  let el = equiv;
  const path = [];
  while (el && el !== document.body) {
    path.push({ tag: el.tagName, id: el.id, class: el.className });
    el = el.parentElement;
  }
  return path;
});
