const res = await tool.fetch_url({
  url: "https://binaries.vodafone.co.uk/gbnnsauqav4t/5xBFDuXivfW8gaQl2eulf8/bd6e9739f7f519a1c42624d9c2c01d53/hbb-price-plan-260225.pdf"
});

console.log("Status:", res.status);
console.log("Body length:", res.body ? res.body.length : 0);

// Let's search inside the PDF raw stream for text mentions of "Xtra", "40", "Full Fibre", "Apple TV", etc.
if (res.body) {
  const matches = [];
  const regex = /(Xtra|Full Fibre|Apple TV|speed|bundle|tier|Broadband)/gi;
  let match;
  // Look for text fragments
  // In PDF streams, text often appears inside parentheses or plain strings like (Xtra)
  const textMatches = Array.from(res.body.matchAll(/\(([^()]{3,80})\)/g)).map(m => m[1]);
  console.log("Found text fragments in PDF:", textMatches.length);
  const relevant = textMatches.filter(t => /xtra|fibre|broadband|tier|apple|speed|40/i.test(t));
  console.log("Relevant text fragments:", relevant.slice(0, 40));
}

