const tabId = 480038501;
const pageData = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll("a")).map(a => ({
    text: a.innerText.replace(/\n+/g, " ").trim(),
    href: a.href
  })).filter(l => l.text.length > 0);

  // Let's also check services dropdown or pricing details on page
  const text = document.body.innerText;

  return {
    links: links.slice(0, 40),
    pricingSnippets: Array.from(text.matchAll(/(?:price|pricing|£[\d\.]+)[^\n]*/gi)).map(m => m[0]).slice(0, 20)
  };
});

console.log("Links found:\n", JSON.stringify(pageData.links.slice(0, 25), null, 2));
console.log("Pricing snippets:\n", JSON.stringify(pageData.pricingSnippets, null, 2));

